// The art ids, read from the manifest when the page opens, so an id a later package adds shows up here with no edit.
// An id with a customer file is drawn from its own generated file; an id with only a private track shows an honest plate:
// the app never draws a stand-in picture as if it were the art (spec 8.2).
import { useEffect, useState } from 'react'
import { ART_MANIFEST, ART_TRACK, artEntry, artText, artUrl } from '../../art'
import type { GalleryEntryX } from '../types'

type Loaded = { kind: 'img'; url: string } | { kind: 'txt'; text: string } | { kind: 'none' }

function ArtPlate({ id }: { id: string }) {
  const [got, setGot] = useState<Loaded | null>(null)
  const row = ART_MANIFEST.art[id]
  useEffect(() => {
    let live = true
    const e = artEntry(id)
    if (!e) { setGot({ kind: 'none' }); return }
    const p = e.kind === 'txt' ? artText(id).then((t): Loaded => (t ? { kind: 'txt', text: t } : { kind: 'none' })) : artUrl(id).then((u): Loaded => (u ? { kind: 'img', url: u } : { kind: 'none' }))
    p.then((v) => { if (live) setGot(v) }, () => { if (live) setGot({ kind: 'none' }) })
    return () => { live = false }
  }, [id])
  return (
    <figure className="gl-artplate">
      <div className="gl-artplate-box">
        {got?.kind === 'img' && <img src={got.url} alt="" width={160} height={160} />}
        {got?.kind === 'txt' && <pre className="gl-artplate-txt" aria-hidden="true">{got.text}</pre>}
        {got?.kind === 'none' && <span className="gl-artplate-none">{row?.track === 'private-only' ? 'private track only: no customer file' : 'no file for this track'}</span>}
        {got === null && <span className="gl-artplate-none">loading</span>}
      </div>
      <figcaption className="gl-artplate-cap">
        <code>{id}</code>
        <span>{row ? `${row.track}, ${row.files.length} file${row.files.length === 1 ? '' : 's'}, budget ${row.budget_bytes} B` : 'not in the manifest'}</span>
      </figcaption>
    </figure>
  )
}

function ArtIds() {
  const ids = Object.keys(ART_MANIFEST.art).sort()
  return <div className="gl-artgrid">{ids.map((id) => <ArtPlate key={id} id={id} />)}</div>
}

const entries: GalleryEntryX[] = [
  {
    id: 'manifest/art-ids',
    title: 'Art ids',
    group: 'art',
    merged: 'art pipeline, 12 Nov',
    note: `Every id of the art manifest on the ${ART_TRACK} track. Pictures here are generated by tools/art from seeded noise or own work; no third-party picture is in a tracked path.`,
    states: [{ label: `${Object.keys(ART_MANIFEST.art).length} ids`, node: <ArtIds /> }],
  },
]
export default entries
